283				v, err := s.Publish(contestOrg, 2, candidate)
284				results <- outcome{"publish", v, err}
285			}()
286			go func() {
287				defer wg.Done()
288				<-start
289				v, err := s.Rollback(contestOrg, 2, 1)
290				results <- outcome{"rollback", v, err}
291			}()
292			close(start)
293			wg.Wait()
294			close(results)
